# Harwin Gecko (G125) 1.25 mm pitch connectors, widely used on CubeSat boards. Outline derived from the pitch and Harwin catalogue values; marked derived.
for pins in (4, 6, 10, 12, 20):
    rows = 2
    length = 1.25 * (pins / rows - 1) + 5.2
    PARTS.append(part("harwin_gecko_g125_" + str(pins), "Harwin Gecko G125 " + str(pins) + "-way male PCB connector (1.25 mm pitch)", "harness", "connector", "Harwin", "G125-MH1" + format(pins, "02d") + "05-0300", (round(length, 2), 5.0, 4.6), round(0.35 * pins + 0.3, 1), {"kind": "box", "x": round(length, 2), "y": 5.0, "z": 4.6},
        source("derived", "https://www.harwin.com/connectors/gecko/", "Harwin Gecko product family page (read 2026-11-08: 1.25 mm pitch, 2.8 A per contact, -65 to 150 C)", ["electrical", "thermal"], notes="Outline derived: (pins/2 - 1) x 1.25 mm + 5.2 mm housing, 5.0 x 4.6 mm section; mass derived (0.35 g per contact). Exact outline is in the Harwin G125 drawing."), vendor_country="UK", distributors=["Digi-Key", "Mouser", "Farnell", "direct"], status="in_production", mass_note="derived", dimensions_note="derived",
        electrical={"rating": "2.8 A per contact, 1.25 mm pitch", "contacts": pins}, thermal={"operating_temperature_C": {"min": -65, "max": 150}}, connectors=["Gecko G125 " + str(pins) + "-way (mates with G125 female cable connector)"], cost=cost(basis="list_price", currency="USD"), cost_note="a few USD each at distributors"))
